    CONSTRAINT subscriptions_subscriptionplan_max_learners_check CHECK ((max_learners >= 0)),
    CONSTRAINT subscriptions_subscriptionplan_max_tests_check CHECK ((max_tests >= 0)),
    CONSTRAINT subscriptions_subscriptionplan_sort_order_check CHECK ((sort_order >= 0))
);


